function sameRunComparison(p){
 const diff=(a,b)=>[...new Set([...Object.keys(a),...Object.keys(b)])].sort().filter(k=>(a[k]||0)!==(b[k]||0)).map(key=>({key,web:a[key]||0,native:b[key]||0,delta:(b[key]||0)-(a[key]||0)}));
 const counts=(xs,key)=>{const z={};for(const x of xs){const k=key(x);z[k]=(z[k]||0)+1;}return z;};
 const groupKey=c=>c.status==="unknown"?"unknown":c.rpcAction?JSON.stringify(["RPC",c.method,c.rpcAction]):JSON.stringify([c.route,c.method,null]);
 const flatten=w=>[
 ...w.invocations.flatMap(i=>i.rows.map(r=>({...r,originalContext:i.context,comparisonContext:groupKey(i.context),invocationId:i.context.invocationId,httpInvocationId:i.context.httpInvocationId}))),
 ...w.unknownRows.map(r=>({...r,originalContext:{status:"unknown"},comparisonContext:"unknown",invocationId:null,httpInvocationId:null}))
 ].sort((a,b)=>a.ordinal-b.ordinal);
 const summarize=rows=>({queryCalls:rows.length,contexts:counts(rows,r=>r.comparisonContext),statements:counts(rows,r=>r.statement),scopes:counts(rows,r=>r.scope),unknownContext:rows.filter(r=>r.comparisonContext==="unknown").length,unknownStatement:rows.filter(r=>r.statement==="unknown").length,unknownPartition:counts(rows,r=>JSON.stringify([r.comparisonContext==="unknown",r.statement==="unknown"]))});
 const windows={};
 for(const [name,w]of Object.entries(p.windows)){
  const rows=flatten(w),switchInvocation=w.invocations.find(x=>x.context.rpcAction==="workspace.switchWorkspace"),switchComplete=switchInvocation?.receipt?.completedAt?Date.parse(switchInvocation.receipt.completedAt):null;
  const groups={}; for(const i of w.invocations){
   const key=groupKey(i.context); (groups[key]??=[]).push({originalContext:i.context,queryCalls:i.rows.length,firstOrdinal:i.rows[0]?.ordinal??null,lastOrdinal:i.rows.at(-1)?.ordinal??null,startedAt:i.receipt?.startedAt??null,completedAt:i.receipt?.completedAt??null,httpStatus:i.receipt?.httpStatus??null,
    startRelativeMs:i.receipt?.startedAt?Date.parse(i.receipt.startedAt)-Date.parse(w.total.startedAt):null,
    endRelativeMs:i.receipt?.completedAt?Date.parse(i.receipt.completedAt)-Date.parse(w.total.startedAt):null,
    startAfterSwitchCompleteMs:switchComplete&&i.receipt?.startedAt?Date.parse(i.receipt.startedAt)-switchComplete:null,
    endAfterSwitchCompleteMs:switchComplete&&i.receipt?.completedAt?Date.parse(i.receipt.completedAt)-switchComplete:null,
    statements:i.statementCounts,scopes:i.scopeCounts,rows:i.rows
   });
  }
  const phases=w.segments.map((s,i)=>{
   const from=w.checkpoints[i].queryCalls,to=w.checkpoints[i+1].queryCalls,rs=rows.filter(r=>r.ordinal>from&&r.ordinal<=to);if(rs.length!==s.queryCalls)throw new Error("phase ordinal mismatch "+name);
   return {name:s.phase,startedAt:s.startedAt,finishedAt:s.finishedAt,durationMs:s.durationMs,fromExclusive:from,toInclusive:to,...summarize(rs),rows:rs};
  });
  windows[name]={window:{startedAt:w.total.startedAt,finishedAt:w.total.finishedAt,durationMs:w.total.durationMs,fromExclusive:w.ordinalFrom,toInclusive:w.ordinalTo},summary:summarize(rows),phases,groups,physicalRPC:w.physicalRPC,logicalRPC:w.logicalRPC,crossingReceipts:w.crossingReceipts};
 }
 function comparison(web,native){
  const a=windows[web],b=windows[native],comp=x=>diff(a.summary[x],b.summary[x]);
  const groupPairs={};for(const k of new Set([...Object.keys(a.groups),...Object.keys(b.groups)])){
   const x=a.groups[k]??[],y=b.groups[k]??[];
   groupPairs[k]={webQueries:x.reduce((s,r)=>s+r.queryCalls,0),nativeQueries:y.reduce((s,r)=>s+r.queryCalls,0),webInvocations:x.length,nativeInvocations:y.length,pairs:Array.from({length:Math.min(x.length,y.length)},(_,i)=>({call:i+1,webQueries:x[i].queryCalls,nativeQueries:y[i].queryCalls,delta:y[i].queryCalls-x[i].queryCalls,statementDeltas:diff(x[i].statements,y[i].statements),scopeDeltas:diff(x[i].scopes,y[i].scopes)})),webUnpaired:x.slice(y.length),nativeUnpaired:y.slice(x.length)};
  }
  return {web,native,queryDelta:b.summary.queryCalls-a.summary.queryCalls,contextDeltas:comp("contexts"),statementDeltas:comp("statements"),scopeDeltas:comp("scopes"),unknownPartitionDeltas:comp("unknownPartition"),groupPairs};
 }
 const full=comparison("webLogin","nativeLogin"),first=comparison("startup-hosted","startup-bundled");
 const fullPhasePairs=windows.webLogin.phases.map((a,i)=>{const b=windows.nativeLogin.phases[i];return{webPhase:a.name,nativePhase:b.name,webQueries:a.queryCalls,nativeQueries:b.queryCalls,delta:b.queryCalls-a.queryCalls,contextDeltas:diff(a.contexts,b.contexts),statementDeltas:diff(a.statements,b.statements),scopeDeltas:diff(a.scopes,b.scopes),unknownPartitionDeltas:diff(a.unknownPartition,b.unknownPartition)};});
