 const boundaryPairs=ordered.slice(1).map((b,i)=>{const a=ordered[i];return {previous:a.name,next:b.name,timeGapMs:Date.parse(b.startedAt)-Date.parse(a.finishedAt),queryCounterGap:b.fromExclusive-a.toInclusive,previousOrdinalInclusive:a.toInclusive,nextOrdinalExclusive:b.fromExclusive,overlappingOrdinals:Math.max(0,a.toInclusive-b.fromExclusive)};});
 return {windows,fullComparison:full,firstComparison:first,fullPhasePairs,orderedWindows:ordered,boundaryPairs};
}
